{'name': 'RapidAPI', 'api_name': 'requests.get', 'description': 'WHOIS API (v2) returns well-parsed WHOIS records with fields in XML and JSON formats for any IPv4, IPv6 address, domain name, or email.', 'parameters': [{'name': 'domainname', 'description': 'The name of the domain looked up.', 'type': 'STRING'}, {'name': 'thinwhois', 'description': '1 results in returning whois data from the registry only, without fetching data from the registrar. Returned registry data are to be found in the WhoisRecord → registryData schema element. Accepted values are 0 and 1, the default is 0.', 'type': 'STRING'}, {'name': 'callback', 'description': 'A JAVAscript function used when outputFormat is JSON; this is an implementation known as JSONP which invokes the callback on the returned response.', 'type': 'STRING'}, {'name': 'preferfresh', 'description': 'Can be 0 or 1. 1 results in getting the latest Whois record even if it is incomplete. Defaults to 0.', 'type': 'STRING'}, {'name': 'checkproxydata', 'description': '1 results in fetching proxy/whois guard data, if found, they are returned in the WhoisRecord → privateWhoisProxy schema element. Accepted values are 0 and 1, the default is 0.', 'type': 'STRING'}, {'name': '_parse', 'description': 'This parameter enables the use of the API for parsing WHOIS raw text provided in the query.1 provides parsing for input WHOIS raw texts described at the parameters registryRawText and registrarRawText. Accepted values are 0 and 1, the default is 0.', 'type': 'STRING'}, {'name': 'registryrawtext', 'description': 'The string containing the registry WHOIS raw text to be parsed; works only when the _parse parameter is equal to 1.', 'type': 'STRING'}, {'name': 'registrarrawtext', 'description': 'A string containing the registrar WHOIS raw text to be parsed; works only when the _parse parameter is equal to 1.', 'type': 'STRING'}, {'name': 'ipwhois', 'description': '1 results in returning the WHOIS record for the hosting IP if the WHOIS record for the domain is not supported. For unsupported TLDs, domain NameServers are returned if the ipWhois flag is activated, a WHOIS record for the hosting IP is added to the result.  Accepted values are 0 and 1, the default is 0.', 'type': 'STRING'}, {'name': 'ip', 'description': 'Return IPs for the domain name. Accepted values are 0 and 1. Defaults to 0: no IPs are returned. 1 results in returning IPs.', 'type': 'STRING'}, {'name': 'da', 'description': 'Perform domain availability check. Accepted values are 0, 1 and 2. Defaults to 0: no domain availability check is performed. When set to 1 the result contains a quick check on domain availability, 2 is slower but more accurate. Results are returned under WhoisRecord → domainAvailability (AVAILABLE | UNAVAILABLE | UNDETERMINED).', 'type': 'STRING'}, {'name': 'outputformat', 'description': 'Response output format.  Acceptable values: XML or JSON. Defaults to XML.', 'type': 'STRING'}]}
